/*
 *  monologue.cpp — monologue-style voice for the Korg NTS-1, generated by korgTools.
 *  Six knobs are live, plus A (VCO1 SHAPE) and ALT-A (VCO2 SHAPE); the rest is baked in.
 */
#include "userosc.h"
#include <cmath>
#include <cstdint>

#define NPARAMS 24
static int32_t p_[NPARAMS] = {0, 0, 0, 100, 0, 0, 0, 0, 25, 80, 0, 40, 1, 0, 30, 65, 1, 1, 40, 0, 0, 0, 20, 80};
static const int32_t kLiveIdx[6] = {8, 9, 15, 13, 14, 11};
static const int32_t kLiveMin[6] = {0, 0, -100, 0, 0, 0};
static const int32_t kLiveMax[6] = {100, 100, 100, 100, 100, 100};

static inline void setLive(int which, uint16_t raw) {
  int32_t v = (int32_t)(int16_t)raw;
  if (v < kLiveMin[which]) v = kLiveMin[which];
  if (v > kLiveMax[which]) v = kLiveMax[which];
  p_[kLiveIdx[which]] = v;
}

/* ---- monologue-style voice core, generated by korgTools ---- */
static const float kSR = 48000.f;
static const float kPi = 3.14159265358979f;

struct MonoState {
  float ph1, ph2, lfoPh, l1, l2, nlp, eg, amp, cur, target, vel, bend;
  int stage, gate, lfoDone;
  uint32_t seed;
};
static MonoState m_ = {0, 0, 0, 0, 0, 0, 0, 0, 60.f, 60.f, 100.f, 0, 0, 0, 0, 0x12345678u};

static inline float fastTanh(float x) {
  if (x < -3.f) return -1.f;
  if (x > 3.f) return 1.f;
  const float x2 = x * x;
  return x * (27.f + x2) / (27.f + 9.f * x2);
}
static inline float blep(float t, float dt) {
  if (t < dt) { t /= dt; return t + t - t * t - 1.f; }
  if (t > 1.f - dt) { t = (t - 1.f) / dt; return t * t + t + t + 1.f; }
  return 0.f;
}
static inline float clamp4(float x) { return x > 4.f ? 4.f : (x < -4.f ? -4.f : x); }
static inline float knobTime(int32_t v) { return 0.001f * powf(5000.f, v / 100.f); }
static inline float knobHz(int32_t v) { return 20.f * powf(1000.f, v / 100.f); }
static inline float coefFor(float sec) { return expf(-4.6f / (sec * kSR)); }
static inline float pulse(float t, float dt, float w) {
  float f = t + 1.f - w; if (f >= 1.f) f -= 1.f;
  return (t < w ? 1.f : -1.f) + blep(t, dt) - blep(f, dt);
}
static inline float fold(float x) {
  float f = (x + 1.f) * 0.25f; f -= floorf(f);
  return 1.f - 4.f * fabsf(f - 0.5f);
}
static inline float sawShaped(float t, float dt, float s) {
  float tb = t + 0.5f; if (tb >= 1.f) tb -= 1.f;
  const float a = 2.f * t - 1.f - blep(t, dt);
  const float b = 2.f * tb - 1.f - blep(tb, dt);
  return (a + s * b) / (1.f + s * 0.5f);
}
static inline float monoNoise() {
  uint32_t s = m_.seed;
  s ^= s << 13; s ^= s >> 17; s ^= s << 5; m_.seed = s;
  return s / 2147483648.f - 1.f;
}
static inline float monoSvf(float x, float fc, int32_t res) {
  if (fc > kSR * 0.45f) fc = kSR * 0.45f;
  const float g = tanf(kPi * fc / kSR);
  const float k = 2.f - 1.98f * (res / 100.f);
  const float yh = (x - (k + g) * m_.l1 - m_.l2) / (1.f + k * g + g * g);
  const float yb = fastTanh(g * yh + m_.l1);
  m_.l1 = clamp4(g * yh + yb);
  const float yl = g * yb + m_.l2;
  m_.l2 = clamp4(g * yb + yl);
  return yl;
}
static inline void monoReset() {
  m_.ph1 = m_.ph2 = m_.lfoPh = m_.l1 = m_.l2 = m_.nlp = m_.eg = m_.amp = m_.bend = 0.f;
  m_.stage = m_.gate = m_.lfoDone = 0;
}
static inline void monoNoteOn(const int32_t * v, float note, float vel) {
  if (m_.stage == 0 && m_.gate == 0) m_.cur = note;
  m_.target = note; m_.vel = vel; m_.stage = 1; m_.gate = 1;
  if (v[17] == 2) { m_.lfoPh = 0.f; m_.lfoDone = 0; }
}
static inline void monoNoteOff() { m_.gate = 0; }

struct MonoBlk { float atk, dc, egInt, lfoInt, lfoInc, gc, velGain, drive, cutBase, oct; int32_t egType; };
static inline void monoPrep(const int32_t * v, MonoBlk & b) {
  b.egType = v[12];
  b.atk = 1.f / (knobTime(v[13]) * kSR); b.dc = coefFor(knobTime(v[14]));
  b.egInt = v[15] / 100.f; b.lfoInt = v[19] / 100.f;
  const float lfoHz = v[17] == 0 ? 1.f * powf(200.f, v[18] / 100.f) : 0.05f * powf(200.f, v[18] / 100.f);
  b.lfoInc = lfoHz / kSR;
  b.gc = v[22] == 0 ? 0.f : coefFor(knobTime(v[22]) * 0.2f);
  b.velGain = 0.5f + 0.5f * (m_.vel / 127.f);
  b.drive = 1.f + (v[11] / 100.f) * 4.f;
  b.cutBase = knobHz(v[8]);
  b.oct = (float)((v[2] - 1) * 12);
}
static inline float monoTick(const int32_t * v, const MonoBlk & b) {
  if (m_.stage == 1) { m_.eg += b.atk; if (m_.eg >= 1.f) { m_.eg = 1.f; m_.stage = 2; } }
  else if (m_.stage == 2) {
    if (b.egType == 1 && m_.gate == 1) m_.eg = 1.f;
    else { m_.eg *= b.dc; if (m_.eg < 1e-5f) { m_.eg = 0.f; m_.stage = 0; } }
  }
  if (b.egType == 0) m_.amp += ((float)m_.gate - m_.amp) * 0.005f;
  else m_.amp = m_.eg;
  m_.cur = m_.target + (m_.cur - m_.target) * b.gc;
  if (m_.lfoDone == 0) {
    m_.lfoPh += b.lfoInc;
    if (m_.lfoPh >= 1.f) { if (v[17] == 2) { m_.lfoPh = 0.999999f; m_.lfoDone = 1; } else m_.lfoPh -= 1.f; }
  }
  const float lp = m_.lfoPh;
  const float lfo = v[16] == 0 ? (lp < 0.5f ? 1.f : -1.f) : (v[16] == 1 ? 1.f - 4.f * fabsf(lp - 0.5f) : 2.f * lp - 1.f);
  const float lfoMod = lfo * b.lfoInt;
  const float egMod = m_.eg * b.egInt;
  const float nz = monoNoise();
  float base = m_.cur + m_.bend + b.oct;
  if (v[21] == 2) base += lfoMod * 12.f;
  if (v[20] == 2) base += egMod * 24.f;
  float n2 = base + v[6];
  if (v[20] == 1) n2 += egMod * 24.f;
  float s1 = v[1] / 100.f, s2 = v[5] / 100.f;
  if (v[21] == 1) { s1 += lfoMod * 0.5f; s2 += lfoMod * 0.5f; }
  s1 = s1 < 0.f ? 0.f : (s1 > 1.f ? 1.f : s1);
  s2 = s2 < 0.f ? 0.f : (s2 > 1.f ? 1.f : s2);
  float dt1 = 440.f * powf(2.f, (base - 69.f) / 12.f) / kSR; if (dt1 > 0.45f) dt1 = 0.45f;
  float dt2 = 440.f * powf(2.f, (n2 - 69.f) / 12.f) / kSR; if (dt2 > 0.45f) dt2 = 0.45f;
  m_.ph1 += dt1;
  int wrapped = 0;
  if (m_.ph1 >= 1.f) { m_.ph1 -= 1.f; wrapped = 1; }
  m_.ph2 += dt2; if (m_.ph2 >= 1.f) m_.ph2 -= 1.f;
  if (v[10] == 2 && wrapped == 1) m_.ph2 = m_.ph1 * (dt2 / dt1);
  const float t1 = m_.ph1, t2 = m_.ph2;
  float o1;
  if (v[0] == 0) o1 = sawShaped(t1, dt1, s1);
  else if (v[0] == 1) o1 = fold((1.f - 4.f * fabsf(t1 - 0.5f)) * (1.f + 3.f * s1));
  else o1 = pulse(t1, dt1, 0.5f - 0.45f * s1);
  float o2;
  if (v[4] == 0) o2 = sawShaped(t2, dt2, s2);
  else if (v[4] == 1) o2 = fold((1.f - 4.f * fabsf(t2 - 0.5f)) * (1.f + 3.f * s2));
  else { m_.nlp += (nz - m_.nlp) * (1.f - 0.95f * s2); o2 = m_.nlp; }
  if (v[10] == 1) o2 *= o1;
  const float mix = (o1 * v[3] + o2 * v[7]) / 100.f;
  const float x = fastTanh(mix * 0.6f * b.drive);
  float cut = b.cutBase * powf(2.f, (m_.cur - 60.f) / 24.f);
  if (v[20] == 0) cut *= powf(2.f, egMod * 6.f);
  if (v[21] == 0) cut *= powf(2.f, lfoMod * 3.f);
  if (cut < 20.f) cut = 20.f;
  const float y = monoSvf(x, cut, v[9]);
  return fastTanh(y) * m_.amp * b.velGain * (v[23] / 100.f) * 0.5f;
}

static inline int32_t toQ31(float x) {
  if (x >= 0.99999f) x = 0.99999f;
  if (x <= -0.99999f) x = -0.99999f;
  return (int32_t)(x * 2147483648.f);
}
static inline float noteOf(const user_osc_param_t * const params) {
  return (float)(params->pitch >> 8) + (float)(params->pitch & 0xFF) * 0.00392156862745098f;
}

void OSC_INIT(uint32_t platform, uint32_t api) { (void)platform; (void)api; monoReset(); }
void OSC_NOTEON(const user_osc_param_t * const params) { monoNoteOn(p_, noteOf(params), 127.f); }
void OSC_NOTEOFF(const user_osc_param_t * const params) { (void)params; monoNoteOff(); }
void OSC_MUTE(const user_osc_param_t * const params) { (void)params; monoReset(); }
void OSC_VALUE(uint16_t value) { (void)value; }
void OSC_PARAM(uint16_t index, uint16_t value) {
  switch (index) {
    case k_user_osc_param_id1: setLive(0, value); break; // CUTOFF
    case k_user_osc_param_id2: setLive(1, value); break; // RESO
    case k_user_osc_param_id3: setLive(2, value); break; // EG INT
    case k_user_osc_param_id4: setLive(3, value); break; // ATTACK
    case k_user_osc_param_id5: setLive(4, value); break; // DECAY
    case k_user_osc_param_id6: setLive(5, value); break; // DRIVE
    case k_user_osc_param_shape: p_[1] = (int32_t)(value * 100 / 1023); break;
    case k_user_osc_param_shiftshape: p_[5] = (int32_t)(value * 100 / 1023); break;
    default: break;
  }
}
void OSC_CYCLE(const user_osc_param_t * const params, int32_t *yn, const uint32_t frames) {
  m_.target = noteOf(params);
  MonoBlk b; monoPrep(p_, b);
  int32_t * __restrict y = yn;
  const int32_t * const y_e = yn + frames;
  for (; y != y_e; ) { const float s = monoTick(p_, b); *(y++) = toQ31(s); }
}
